		// Convert from MM/DD/YYYY to YYYY-MM-DD
		bdayParts := strings.Split(birthday, "/")
		bdayStr := fmt.Sprintf("%s-%02s-%02s", bdayParts[2], bdayParts[0], bdayParts[1])

