			if j > 0 {
				fmt.Printf(",\n")
			}
			fmt.Printf("      {\n        \"FirstName\": \"%s\",\n        \"LastName\": \"%s\",\n        \"Relationship\": \"%s\"\n      }", 
				relative.FirstName, relative.LastName, relative.Relationship)
		}
		fmt.Printf("\n    ]\n  }")
	}
	fmt.Printf("\n]")
}

func calculateAge(birthday, referenceDate string) int {
	bday, _ := time.Parse("2006-01-02", birthday)
	ref, _ := time.Parse("2006-01-02", referenceDate)

	age := ref.Year() - bday.Year()

	// Check if birthday hasn't occurred yet this year
	if ref.Month() < bday.Month() || (ref.Month() == bday.Month() && ref.Day() < bday.Day()) {
		age--
	}

	return age
}
