const rows = lines.slice(1);

// Process each row
const result = rows.map(row => {
  const values = row.split(',');
  const person: any = {};

  // Map headers to values
  headers.forEach((header, index) => {
    const value = values[index]?.trim();
    if (value && value !== 'null') {
      person[header] = value;
    }
  });

  // Transform data
  const firstName = person.Name.split(' ')[0];
  const lastName = person.Name.split(' ').slice(-1)[0];

  // Convert birthday format
  const birthdayParts = person.Birthday.split('/');
  const birthday = `${birthdayParts[2]}-${birthdayParts[0].padStart(2, '0')}-${birthdayParts[1].padStart(2, '0')}`;

  // Calculate age
  const age = calculateAge(birthday);

  // Build relatives array
  const relatives = [];

  // Add father
  if (person.Father) {
    const [fFirstName, fLastName] = person.Father.split(' ');
    relatives.push({
      FirstName: fFirstName,
      LastName: fLastName,
      Relationship: "Father"
    });
  }

  // Add mother
  if (person.Mother) {
    const [mFirstName, mLastName] = person.Mother.split(' ');
    relatives.push({
      FirstName: mFirstName,
      LastName: mLastName,
      Relationship: "Mother"
    });
  }

  // Add brother
  if (person.Brother) {
    const [bFirstName, bLastName] = person.Brother.split(' ');
    relatives.push({
      FirstName: bFirstName,
      LastName: bLastName,
      Relationship: "Brother"
    });
  }

  // Add sister
  if (person.Sister) {
